/bin/zsh -lc "python3 -c 'import json
from pathlib import Path
x=json.loads(Path(\"input.json\").read_text())
reports={r[\"id\"]:r for r in x[\"reports\"]}
def clip(r):
    return max(0,r[\"start\"]),min(60,r[\"end\"])
def union(intervals):
    out=[]
    for a,b in sorted(intervals):
        if a>=b: continue
        if out and a<=out[-1][1]: out[-1][1]=max(out[-1][1],b)
        else: out.append([a,b])
    return out
def duration(intervals):
    return sum(b-a for a,b in intervals)
retained=[]
for r in x[\"reports\"]:
    correction=reports.get(r[\"superseded_by\"])
    a,b=clip(r)
    if r[\"published\"]>x[\"cutoff\"] or (correction is not None and correction[\"published\"]<=x[\"cutoff\"]): continue
    if a<b and (r[\"kind\"]==\"uncertain\" or (r[\"kind\"]==\"down\" and r[\"authoritative\"])): retained.append(r)
services=[]
fleet=[]
for s in sorted(x[\"services\"]):
    confirmed=union(clip(r) for r in retained if r[\"service\"]==s and r[\"kind\"]==\"down\")
    possible=union(clip(r) for r in retained if r[\"service\"]==s)
    coverage=union(clip(m) for m in x[\"monitors\"] if m[\"service\"]==s)
    observed=sum(max(0,min(b,d)-max(a,c)) for a,b in confirmed for c,d in coverage)
    services.append({\"id\":s,\"confirmed_minutes\":duration(confirmed),\"possible_minutes\":duration(possible),\"unobserved_confirmed_minutes\":duration(confirmed)-observed})
    fleet.extend(confirmed)
print(json.dumps({\"services\":services,\"fleet_confirmed_minutes\":duration(union(fleet)),\"retained_report_ids\":sorted(r[\"id\"] for r in retained)},separators=(\",\",\":\")))
'"

